package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.uiapi.*;
import net.minecraft.client.gui.screen.Screen;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Class choices have their own provenance; legacy/background/custom records are retained separately. */
public final class ProficiencyPickerScreen extends RpgScreen {
    private final DashboardSource source;
    private JsonObject snapshot,baseline,choices;
    private CharacterCanvas pane;
    private boolean dirty,fresh;
    private Runnable resumed;
    public ProficiencyPickerScreen(Screen parent,JsonObject draft){this(parent,draft,new DashboardSource(true,text(draft,"id")));}
    public ProficiencyPickerScreen(Screen parent,JsonObject draft,DashboardSource source){super("Proficiencies",parent);this.source=source;snapshot=draft.deepCopy();baseline=snapshot.deepCopy();choices=SheetSections.raw(draft.getAsJsonObject("sheet"),"creation");}
    @Override protected boolean hasUnsavedChanges(){return dirty;}
    @Override protected int maximumWidth(){return 980;}
    @Override protected void init(){super.init();clearChildren();pane=null;busy=false;fresh=false;footer();footerAction(parent instanceof CharacterWizardScreen?"Save Draft":"Save Choices",0,this::save);footerAction("Refresh",2,this::reload);creatorContinue(CreatorFlow.Step.PROFICIENCIES,this::save);wizardRail(CreatorFlow.Step.PROFICIENCIES,()->!dirty);build();reload();}
    private void reload(){if(busy)return;fresh=false;request(source.read(),source.readArgs(),r->{if(r.code().equals("OK")){snapshot=SnapshotReplies.checked(source,r.data());if(!dirty||choices.equals(SheetSections.raw(snapshot.getAsJsonObject("sheet"),"creation"))){choices=SheetSections.raw(snapshot.getAsJsonObject("sheet"),"creation");dirty=false;baseline=snapshot.deepCopy();}fresh=true;build();message="Historical grants remain separate for DM review.";}else message=r.message()+" Choices retained.";});}
    private void toggle(String category,String key){if(busy)return;var values=new ArrayList<>(DashboardModel.strings(choices,category));if(!values.remove(key)){String clazz=CreationRules.clazz(snapshot.getAsJsonObject("sheet"));int limit=category.equals("skills")?CreationRules.skillCount(clazz):CreationRules.expertiseCount(clazz,CreationRules.level(snapshot.getAsJsonObject("sheet")));if(values.size()>=limit){message="Remove a choice first; all "+limit+" selections are allocated.";return;}values.add(key);}var a=new JsonArray();values.forEach(a::add);choices.add(category,a);if(category.equals("skills")){var legacy=SheetSections.raw(snapshot.getAsJsonObject("sheet"),"proficiencies");if(!ProficiencyModel.contains(legacy,"skills",key)){var experts=new JsonArray();for(var v:choices.getAsJsonArray("expertise"))if(!v.getAsString().equals(key))experts.add(v);choices.add("expertise",experts);}}dirty=true;build();}
    private void build(){int offset=pane==null?0:pane.position();String focus=pane==null?"":pane.focusedKey();if(pane!=null)remove(pane);pane=addDrawableChild(new CharacterCanvas(new UiLayout.Rect(frame.x()+12,frame.y()+36,frame.width()-24,Math.max(12,frame.height()-74-footerExtra()))));var view=snapshot.deepCopy();view.add("sheet",SheetSections.update(view.getAsJsonObject("sheet"),"creation",choices));var sheet=view.getAsJsonObject("sheet");String clazz=CreationRules.clazz(sheet);boolean standard=!CreationRules.skills(clazz).isEmpty();var legacy=SheetSections.raw(sheet,"proficiencies");var effective=SheetSections.read(sheet,"proficiencies");int x=6,w=pane.getWidth()-12,columns=w>=460?3:w>=300?2:1,cw=(w-(columns-1)*8)/columns,y=6,count=array(choices,"skills").size(),limit=CreationRules.skillCount(clazz),expertLimit=CreationRules.expertiseCount(clazz,CreationRules.level(sheet));pane.panel("Class Skill Choices",x,y,w,64);pane.label(standard?clazz+" — "+count+" of "+limit+" selected":"Custom class — record choices with your DM",x+7,y+24,w-14,RpgTheme.GOLD);pane.label(standard?(count<limit?(limit-count)+" more choice"+(limit-count==1?"":"s")+" required":"Class skill choices complete"):"Historical grants stay separate",x+7,y+38,w-14,RpgTheme.TEXT);pane.progress(x+7,y+53,w-14,limit==0?1:(double)count/limit);y+=72;pane.label("✓ Selected · ○ Available · gold: trained",x,y,w,RpgTheme.MUTED);y+=19;boolean showExpert=expertLimit>0||!array(choices,"expertise").isEmpty();pane.control("tools:languages",new RpgButton(x,y,w,19,"Tools / Languages","",()->{if(dirty){message="Save these choices before opening tools and languages.";return;}if(fresh&&!busy)client.setScreen(DashboardEditors.tools(this,snapshot,source));}));y+=25;int skillStride=showExpert?44:25;
        var skills=ProficiencyModel.checks(view,false);for(int i=0;i<skills.size();i++){var c=skills.get(i);String name=c.name();int sx=x+i%columns*(cw+8),sy=y+i/columns*skillStride;boolean selected=ProficiencyModel.contains(choices,"skills",name),eligible=CreationRules.skills(clazz).contains(name),retained=ProficiencyModel.contains(legacy,"skills",name),expert=ProficiencyModel.contains(choices,"expertise",name);var button=pane.control("skill:"+name,new RpgButton(sx,sy,cw,21,(selected?"✓ ":retained?"✓ ":"○ ")+name+" "+(ProficiencyModel.hasScores(view)?signed(c.total()):"—"),"",()->toggle("skills",name)).selected(selected).hint(c.breakdown()+"\n"+(eligible&&!selected&&count>=limit?"Maximum class selections reached; remove an existing choice first.":eligible?clazz+" eligible class choice":retained?"Retained historical grant; DM review":"Not in this class's starting skill list")));button.active=!busy&&(selected||eligible&&count<limit);if(showExpert){var eb=pane.control("expert:"+name,new RpgButton(sx,sy+23,cw,17,"Expertise","",()->toggle("expertise",name)).selected(expert).accessible("Expertise in "+name).hint("Expertise doubles the proficiency bonus for an eligible skill or tool.\n"+(expertLimit<=0?"This class has no Expertise at its recorded level.":!ProficiencyModel.contains(effective,"skills",name)?"Proficiency prerequisite not met.":array(choices,"expertise").size()>=expertLimit&&!expert?"Maximum Expertise choices reached; remove one first.":"Eligible trained skill at this recorded level.")));eb.active=!busy&&(expert||expertLimit>0&&ProficiencyModel.contains(effective,"skills",name)&&array(choices,"expertise").size()<expertLimit);}}
        y+=((skills.size()+columns-1)/columns)*skillStride+7;pane.label("Saving Throws — mandatory class grants",x,y,w,RpgTheme.GOLD);y+=18;var saves=ProficiencyModel.checks(view,true);for(int i=0;i<saves.size();i++){var c=saves.get(i);int sx=x+i%columns*(cw+8),sy=y+i/columns*23;boolean grant=CreationRules.saves(clazz).contains(c.ability());var b=pane.control("save:"+c.ability(),new RpgButton(sx,sy,cw,19,c.name()+" "+signed(c.total())+(grant?" · class":c.proficient()?" · legacy":""),"",()->{}).selected(grant).hint(c.breakdown()+"\n"+(grant?"Granted by "+clazz+"; not a player choice":"Additional grants are retained for DM review")));b.active=false;}y+=((6+columns-1)/columns)*23+7;
        if(showExpert){pane.label(expertLimit>0?"Expertise — "+array(choices,"expertise").size()+" of "+expertLimit+" selected":"No class Expertise at this recorded level",x,y,w,RpgTheme.GOLD);y+=19;if(clazz.equals("Rogue")){boolean selected=ProficiencyModel.contains(choices,"expertise","Thieves' tools");var b=pane.control("expert:tools",new RpgButton(x,y,w,19,"Thieves' tools "+(selected?"· Expertise":"· mandatory proficiency"),"",()->toggle("expertise","Thieves' tools")).selected(selected).hint("Rogue Expertise can select thieves' tools instead of one proficient skill."));b.active=!busy&&(selected||array(choices,"expertise").size()<expertLimit);y+=24;}
        }
        if(!standard){var manual=pane.control("manual:grants",new RpgButton(x,y,w,19,"Record Custom Grants — DM Review","",()->{if(fresh&&!busy&&!dirty)client.setScreen(DashboardEditors.proficiencies(this,snapshot,source));}));manual.active=fresh&&!busy&&!dirty;y+=24;}
        pane.wrapped("Tools: "+String.join(", ",DashboardModel.strings(effective,"tools"))+"   Languages: "+String.join(", ",DashboardModel.strings(effective,"languages")),x,y,w,RpgTheme.MUTED);y+=28;for(String warning:CreationRules.warnings(sheet)){pane.wrapped(warning,x,y,w,RpgTheme.MUTED);y+=net.minecraft.client.MinecraftClient.getInstance().textRenderer.getTextHandler().wrapLines(warning,w,net.minecraft.text.Style.EMPTY).size()*12+4;}for(String error:CreationRules.choiceErrors(sheet,false)){pane.wrapped(error,x,y,w,RpgTheme.ERROR);y+=net.minecraft.client.MinecraftClient.getInstance().textRenderer.getTextHandler().wrapLines(error,w,net.minecraft.text.Style.EMPTY).size()*12+4;}pane.position(offset);if(!focus.isEmpty()){pane.focus(focus);setInitialFocus(pane);}}
    private void save(){save(()->{});}
    private void save(Runnable after){if(!fresh||busy){message="Refresh before saving; choices retained.";return;}var preview=SheetSections.update(snapshot.getAsJsonObject("sheet"),"creation",choices);var errors=CreationRules.choiceErrors(preview,false);if(!errors.isEmpty()){message=String.join(" ",errors);messageColor=RpgTheme.ERROR;return;}if(!dirty){message="Draft saved.";after.run();return;}if(needsEditReview(baseline,snapshot)){long expected=revision(snapshot);client.setScreen(new RpgConfirmationScreen(this,"Review changed choices?","Saved data changed. Review it before applying these retained class choices.",()->{if(revision(snapshot)==expected){baseline=snapshot.deepCopy();resumed=()->save(after);}}));return;}fresh=false;saveDraftRequest(source.edit(),source.sectionArgs(snapshot,"creation",choices),next->{snapshot=SnapshotReplies.checked(source,next);dirty=false;fresh=true;baseline=snapshot.deepCopy();message="Draft saved.";build();return true;},after);}

    @Override public void tick(){super.tick();if(resumed!=null&&!busy&&fresh){var next=resumed;resumed=null;next.run();}}
    @Override public void close(){if(busy)return;if(dirty)client.setScreen(new RpgConfirmationScreen(this,"Discard unsaved choices?","Acknowledged choices remain saved.",()->returnFromWizard(CreatorFlow.Step.PROFICIENCIES)));else if(parent instanceof CharacterWizardScreen)returnFromWizard(CreatorFlow.Step.PROFICIENCIES);else super.close();}
    private static String signed(int n){return (n>=0?"+":"")+n;}
}
